        <button onClick={buildConsolidated} className="flex-1 min-w-[170px] bg-[var(--secondary-bg)] text-white font-extrabold rounded-2xl px-4 py-3.5 text-[14px] flex items-center justify-center gap-2"><Sparkles size={17}/>{t("Parecer consolidado")}</button>
