      {weeklySummaryOpen && <section className="card p-5 mt-4" aria-label={t("Resumo da Semana")}><h3 className="font-extrabold text-[18px]">{t("Resumo da Semana")}</h3><p className="text-[13px] text-[var(--muted)] mt-1">Segunda a domingo · {fmtDate(weeklySummary.weekStart)} a {fmtDate(weeklySummary.weekEnd)}</p><ul className="mt-4 space-y-3 text-[14px] leading-relaxed"><li><b>{t("Total de checklists concluídos na semana:")}</b> {weeklySummary.totalConcluded}</li><li><b>{t("% Conformidade média da semana:")}</b> <span style={{color:complianceColor(weeklySummary.avgCompliance)}}>{weeklySummary.avgCompliance}%</span> <span className="text-[var(--muted)]">({weeklySummary.feitos} feitos · {weeklySummary.naoFeitos} não feitos)</span></li><li><b>{t("Top 3 itens mais marcados como Não feito na semana:")}</b>{weeklySummary.top3.length===0 ? <span className="text-[var(--muted)]">{t("Nenhum item marcado como Não feito na semana.")}</span> : <ol className="mt-1 space-y-1 list-decimal pl-5">{weeklySummary.top3.map((t,i)=><li key={`${t.name}-${i}`} className="[overflow-wrap:anywhere]">{t.name} — {t.count}x</li>)}</ol>}</li><li><b>{t("Pessoas com 100% na semana:")}</b>{weeklySummary.perfectPeople.length===0 ? <span className="text-[var(--muted)]">{t("Ninguém com 100% na semana.")}</span> : <span> {weeklySummary.perfectPeople.join(", ")}</span>}</li><li><b>{t("Planos de Ação:")}</b> {weeklySummary.plansResolved} resolvidos / {weeklySummary.plansPending} pendentes</li></ul><button onClick={()=>setWeeklySummaryOpen(false)} className="mt-4 bg-[var(--secondary-bg)] text-[var(--secondary-ink)] font-bold rounded-xl px-4 py-3 text-[13px]">{t("Fechar resumo")}</button></section>}
